// Pure Synthia Automata — experiments/scale: D2 phoneme-sequence benchmark (o_sequence over reused D1 bundles), ported with reproduction gate

/**
 * PORT of pure-synthia-phase1-d1-d2-d31/src/engine/d2-engine.js and
 * src/experiments/d2-benchmark.js (operand builder from src/datasets/d2.js).
 *
 * FROZEN ASSUMPTIONS (D2 contract, pure-synthia-phase1-d1-d2-d31/D2_CONTRACT.md
 * + D2_EXPERIMENT_CONTRACT.md, plus the D1 ASSUMPTIONS.md which D2 inherits):
 *   1. D2 phoneme operands are GENERATED by the D1 path (o_bundle over the
 *      frozen feature inventory) — never instantiated as opaque atoms.
 *   2. The 12-sequence inventory and 9/3 split are frozen implementation
 *      choices, not linguistic completeness claims.
 *   3. Held-out ids never enter discovery generation.
 *   4. Correctness is exact canonical-signature equality; order sensitivity
 *      requires signature(A,B) !== signature(B,A) for differing operands.
 *   5. The compression encoding (L_direct = 48, L_grammar = 112) is a frozen
 *      benchmark convention, not a universal MDL claim.
 *   6. `removeSequence` ablation is a declared structural zero (word/sequence
 *      generation cannot occur without the ordering operator), frozen as
 *      ablatedAccuracy = 0 in the source benchmark — preserved verbatim.
 * Plus this port's own assumptions:
 *   7. Fixture ids are kept verbatim (see datasets.js header).
 *   8. The reproduction gate compares against sealed D2_RESULTS.json
 *      field-by-field; nothing is dropped silently.
 *
 * PROVENANCE (runtime mirror in report.provenance): see D2_PROVENANCE below.
 */

import {
  D1_CONTRACT_VERSION, createD1PrimitiveRegistry, featureIdsFor, getD1Item,
  D2_ITEMS, D2_DISCOVERY_IDS, D2_TEST_IDS, D2_CONTRACT_VERSION, getD2Item,
} from './datasets.js';
import { createBundleOperator } from './operators.js';
import { createSequenceOperator, canonicalSequenceSignature } from './operators.js';
import { Composite, ScaleDerivation, newBenchmarkLedger, replayMatches, fnv1a32, stableStringify } from './core.js';
import { generateBundle } from './d1.js';
import { ratio, compressionGain, ablationImpact, METRIC_PROVENANCE } from './metrics.js';
import { SEALED_D2_RESULTS } from './sealed-results.js';
import { compareToSealed } from './reproduce.js';

/* ------------------------------------------------- D2 engine (ported) */
/* source: pure-synthia-phase1-d1-d2-d31/src/engine/d2-engine.js */

export const D2_ENGINE_VERSION = '0.2.0';
export const D2_GRAMMAR_VERSION = 'd2.1.0';
export const D2_OPERATOR_VERSION = 'phase1.2.0';

export function generateSequence({ phonemeOperands, sequenceOperator, context = {} }) {
  const ledger = newBenchmarkLedger();

  if (!sequenceOperator) {
    return Object.freeze({ ok: false, reason: 'missing-operator:o_sequence', ledger: ledger.snapshot() });
  }

  if (
    !Array.isArray(phonemeOperands)
    || phonemeOperands.length !== 2
    || phonemeOperands.some((operand) => !operand?.composite?.id)
  ) {
    return Object.freeze({ ok: false, reason: 'invalid-phoneme-operands', ledger: ledger.snapshot() });
  }

  const operands = phonemeOperands.map((operand) => operand.composite);

  ledger.record({
    primitivesActivated: operands.length,
    edgesTraversed: 1,
    operationsExecuted: 1,
    recursionDepth: 2,
    transitionCount: 1,
  });

  const representation = sequenceOperator.apply(operands, context);
  const signature = canonicalSequenceSignature(representation);
  const compositeId = `d2-composite:${fnv1a32(stableStringify(representation))}`;
  const derivationId = `d2-derivation:${fnv1a32(signature)}`;

  ledger.record({ statesGenerated: 1 });

  const composite = new Composite({
    id: compositeId,
    scale: 'symbolic-morpheme-sequence',
    children: operands.map((operand) => operand.id),
    operatorId: sequenceOperator.id,
    representation,
    context,
    derivationId,
  });

  const derivation = new ScaleDerivation({
    id: derivationId,
    engineVersion: D2_ENGINE_VERSION,
    grammarVersion: D2_GRAMMAR_VERSION,
    operatorVersion: D2_OPERATOR_VERSION,
    input: {
      operandCompositeIds: operands.map((operand) => operand.id),
      operandDerivationHashes: phonemeOperands.map((operand) => operand.derivation.hash),
    },
    context,
    steps: [
      { step: 'accept-d1-generated-phonemes', operandIds: operands.map((operand) => operand.id) },
      { step: 'apply-operator', operatorId: sequenceOperator.id },
      { step: 'generate-sequence-composite', compositeId, signature },
    ],
    output: { compositeId, signature, representation },
    ledger: ledger.snapshot(),
  });

  return Object.freeze({ ok: true, composite, derivation, signature });
}

/* ------------------------------------- D1->D2 operand builder (ported) */
/* source: pure-synthia-phase1-d1-d2-d31/src/datasets/d2.js buildD1PhonemeComposite */

export function buildD1PhonemeComposite(label, {
  primitiveRegistry = createD1PrimitiveRegistry(),
  bundleOperator = createBundleOperator(),
} = {}) {
  const d1Item = getD1Item(label);
  const generated = generateBundle({
    featureIds: featureIdsFor(d1Item),
    primitiveRegistry,
    bundleOperator,
    context: { sourceContract: D1_CONTRACT_VERSION, role: 'D2-operand' },
  });

  if (!generated.ok) return generated;

  return Object.freeze({
    ok: true,
    label,
    composite: generated.composite,
    derivation: generated.derivation,
    signature: generated.signature,
  });
}

/* ---------------------------------------------- D2 benchmark (ported) */
/* source: pure-synthia-phase1-d1-d2-d31/src/experiments/d2-benchmark.js */

function buildOperands(item, { primitiveRegistry, bundleOperator }) {
  return item.phonemes.map((label) => buildD1PhonemeComposite(label, { primitiveRegistry, bundleOperator }));
}

function storedDiscoverySolutions({ primitiveRegistry, bundleOperator, sequenceOperator }) {
  const signatures = new Set();

  for (const id of D2_DISCOVERY_IDS) {
    const item = getD2Item(id);
    const phonemeOperands = buildOperands(item, { primitiveRegistry, bundleOperator });

    if (phonemeOperands.some((operand) => !operand.ok)) {
      throw new Error(`D1 operand construction failed for ${id}.`);
    }

    const generated = generateSequence({
      phonemeOperands,
      sequenceOperator,
      context: { dataset: 'D2', split: 'discovery' },
    });

    if (!generated.ok) throw new Error(`D2 discovery generation failed for ${id}.`);

    signatures.add(generated.signature);
  }

  return signatures;
}

function expectedSignature(item, phonemeOperands, sequenceOperator) {
  return canonicalSequenceSignature(
    sequenceOperator.apply(phonemeOperands.map((operand) => operand.composite)),
  );
}

function evaluateHeldout({ id, primitiveRegistry, bundleOperator, sequenceOperator, storedSolutions }) {
  const item = getD2Item(id);
  const phonemeOperands = buildOperands(item, { primitiveRegistry, bundleOperator });

  if (phonemeOperands.some((operand) => !operand.ok)) {
    return Object.freeze({ id, correct: false, novel: false, replayMatch: false, reason: 'd1-operand-generation-failed' });
  }

  const generated = generateSequence({
    phonemeOperands,
    sequenceOperator,
    context: { dataset: 'D2', split: 'test' },
  });

  if (!generated.ok) {
    return Object.freeze({ id, correct: false, novel: false, replayMatch: false, reason: generated.reason });
  }

  const expected = expectedSignature(item, phonemeOperands, sequenceOperator);

  const reversedRepresentation = sequenceOperator.apply([
    phonemeOperands[1].composite,
    phonemeOperands[0].composite,
  ]);
  const reversedSignature = canonicalSequenceSignature(reversedRepresentation);

  return Object.freeze({
    id,
    phonemes: [...item.phonemes],
    correct: generated.signature === expected,
    novel: !storedSolutions.has(generated.signature),
    orderSensitive: generated.signature !== reversedSignature,
    replayMatch: replayMatches(generated.derivation),
    signature: generated.signature,
    reversedSignature,
    derivationHash: generated.derivation.hash,
    operandDerivationHashes: phonemeOperands.map((operand) => operand.derivation.hash),
    ledger: generated.derivation.ledger,
  });
}

function evaluateReconstruction({ item, primitiveRegistry, bundleOperator, sequenceOperator }) {
  const phonemeOperands = buildOperands(item, { primitiveRegistry, bundleOperator });

  if (phonemeOperands.some((operand) => !operand.ok)) {
    return Object.freeze({ id: item.id, correct: false });
  }

  const generated = generateSequence({ phonemeOperands, sequenceOperator });

  if (!generated.ok) return Object.freeze({ id: item.id, correct: false });

  return Object.freeze({
    id: item.id,
    correct: generated.signature === expectedSignature(item, phonemeOperands, sequenceOperator),
  });
}

function orderDestroyedCollisionCount({ primitiveRegistry, bundleOperator }) {
  const signatures = new Map();

  for (const item of D2_ITEMS) {
    const operands = buildOperands(item, { primitiveRegistry, bundleOperator });
    if (operands.some((operand) => !operand.ok)) continue;

    const unordered = operands.map((operand) => operand.composite.id).sort().join('|');
    const existing = signatures.get(unordered) ?? [];
    existing.push(item.id);
    signatures.set(unordered, existing);
  }

  let collisions = 0;
  for (const ids of signatures.values()) {
    if (ids.length > 1) collisions += ids.length - 1;
  }
  return collisions;
}

function aggregateLedger(records) {
  const total = {
    primitivesActivated: 0, statesGenerated: 0, edgesTraversed: 0,
    operationsExecuted: 0, recursionDepth: 0, activeAutomata: 0, transitionCount: 0,
  };

  for (const record of records) {
    if (!record.ledger) continue;
    total.primitivesActivated += record.ledger.primitivesActivated;
    total.statesGenerated += record.ledger.statesGenerated;
    total.edgesTraversed += record.ledger.edgesTraversed;
    total.operationsExecuted += record.ledger.operationsExecuted;
    total.recursionDepth = Math.max(total.recursionDepth, record.ledger.recursionDepth);
    total.activeAutomata = Math.max(total.activeAutomata, record.ledger.activeAutomata);
    total.transitionCount += record.ledger.transitionCount;
  }

  return Object.freeze(total);
}

export const D2_ASSUMPTIONS = Object.freeze([
  'D2 phoneme operands are generated by the D1 o_bundle path, never instantiated as opaque atoms.',
  'The 12-sequence inventory and 9/3 split are frozen implementation choices, not linguistic completeness claims.',
  'Held-out ids never enter discovery generation.',
  'Correctness is exact canonical-signature equality; signature(A,B) !== signature(B,A) for differing operands.',
  'The compression encoding (L_direct=48, L_grammar=112) is a frozen benchmark convention, not a universal MDL claim.',
  'The removeSequence ablation is a declared structural zero (generation cannot occur without the ordering operator), frozen as ablatedAccuracy=0 in the source benchmark.',
]);

export const D2_PROVENANCE = Object.freeze({
  metrics: METRIC_PROVENANCE,
  split: Object.freeze({ status: 'SOURCE_STATEMENT', source: 'pure-synthia-phase1-d1-d2-d31/src/datasets/d2.js (9 discovery / 3 test)' }),
  compression: Object.freeze({ status: 'SOURCE_STATEMENT', source: 'pure-synthia-phase1-d1-d2-d31/D2_EXPERIMENT_CONTRACT.md §11 (12 identities × 4 bits direct; 96 bits references + 16 bits grammar overhead)', directBits: 48, grammarBits: 112 }),
  ablations: Object.freeze({ status: 'SOURCE_STATEMENT', source: 'pure-synthia-phase1-d1-d2-d31/src/experiments/d2-benchmark.js (removeSequence structural zero; removeBundle; destroyOrder collision count)' }),
  versions: Object.freeze({ status: 'SOURCE_STATEMENT', source: 'pure-synthia-phase1-d1-d2-d31/src/engine/d2-engine.js', engine: D2_ENGINE_VERSION, grammar: D2_GRAMMAR_VERSION, operator: D2_OPERATOR_VERSION }),
  machinery: Object.freeze({ status: 'IMPLEMENTATION_CHOICE', source: 'src/engine/{derivation,ledger}.js reused via src/experiments/scale/core.js; sealed hashes reproduced byte-exactly' }),
});

export function runD2Benchmark() {
  const primitiveRegistry = createD1PrimitiveRegistry();
  const bundleOperator = createBundleOperator();
  const sequenceOperator = createSequenceOperator();

  const storedSolutions = storedDiscoverySolutions({ primitiveRegistry, bundleOperator, sequenceOperator });

  const heldout = D2_TEST_IDS.map((id) =>
    evaluateHeldout({ id, primitiveRegistry, bundleOperator, sequenceOperator, storedSolutions }));

  const reconstruction = D2_ITEMS.map((item) =>
    evaluateReconstruction({ item, primitiveRegistry, bundleOperator, sequenceOperator }));

  const generationAccuracy = ratio(heldout.filter((record) => record.correct).length, heldout.length);
  const reconstructionAccuracy = ratio(reconstruction.filter((record) => record.correct).length, reconstruction.length);
  const correctHeldout = heldout.filter((record) => record.correct);
  const novelCompositionRate = ratio(correctHeldout.filter((record) => record.novel).length, correctHeldout.length);
  const orderSensitivity = ratio(heldout.filter((record) => record.orderSensitive).length, heldout.length);
  const derivationIntegrity = ratio(heldout.filter((record) => record.replayMatch).length, heldout.length);

  const directBits = 48;
  const grammarBits = 112;

  // Frozen structural zero: without o_sequence no generation can occur.
  const noSequenceAccuracy = 0;

  const noBundleResults = D2_TEST_IDS.map((id) => {
    const item = getD2Item(id);
    const operands = buildOperands(item, { primitiveRegistry, bundleOperator: null });
    return operands.every((operand) => operand.ok);
  });
  const noBundleAccuracy = ratio(noBundleResults.filter(Boolean).length, noBundleResults.length);

  const unorderedCollisionCount = orderDestroyedCollisionCount({ primitiveRegistry, bundleOperator });

  const report = Object.freeze({
    contractVersion: D2_CONTRACT_VERSION,
    discoveryIds: [...D2_DISCOVERY_IDS],
    testIds: [...D2_TEST_IDS],
    metrics: Object.freeze({
      generationAccuracy,
      reconstructionAccuracy,
      novelCompositionRate,
      orderSensitivity,
      derivationIntegrity,
      compressionGain: compressionGain({ directBits, grammarBits }),
    }),
    compression: Object.freeze({ directBits, grammarBits }),
    ablations: Object.freeze({
      removeSequence: Object.freeze({
        ablatedAccuracy: noSequenceAccuracy,
        impact: ablationImpact(generationAccuracy, noSequenceAccuracy),
      }),
      removeBundle: Object.freeze({
        ablatedAccuracy: noBundleAccuracy,
        impact: ablationImpact(generationAccuracy, noBundleAccuracy),
      }),
      destroyOrder: Object.freeze({ collisionCount: unorderedCollisionCount }),
    }),
    ledger: aggregateLedger(heldout),
    heldout: Object.freeze(heldout),
    reconstruction: Object.freeze(reconstruction),
    assumptions: D2_ASSUMPTIONS,
    provenance: D2_PROVENANCE,
  });

  return Object.freeze({
    ...report,
    reproduction: compareToSealed(SEALED_D2_RESULTS, report),
  });
}

